import { InlineKeyboard, InputFile } from 'grammy';
import { existsSync } from 'node:fs';
import { resolve, dirname } from 'node:path';
import { fileURLToPath } from 'node:url';
import { BotContext } from '../bot.js';
import { cleanAndSend } from '../utils/chat.js';
import { setUserSource } from '../db/users.js';
import { ru } from '../locales/index.js';

// Lead magnet: free guide delivered on `/start gift` or `/start gift__<source>`.
// The deep link is generated by the site page /gift/ (which fires the Meta
// Pixel `Lead` event and encodes utm_* into <source>), or used directly from
// the Instagram bio as `?start=gift__ig_bio`.
//
// Users who come in this way have zero purchases, so the existing cold
// nurture (jobs/nurture.ts, COLD_NURTURE_STEPS) picks them up automatically
// on day 1/3/7 — nothing extra to schedule here.
//
// The PDF itself is NOT tracked in session.botMessageIds on purpose: it is
// the user's gift and must survive the nav cleanup in cleanAndSend.

const __filename = fileURLToPath(import.meta.url);
const ASSETS = resolve(dirname(__filename), '..', '..', 'assets', 'gift');

// One PDF per language; `uk` falls back to `ru` until a Ukrainian render exists.
const GIFT_FILES: Record<string, string> = {
  ru: resolve(ASSETS, 'professional-purpose.ru.pdf'),
  uk: resolve(ASSETS, 'professional-purpose.uk.pdf'),
};
const GIFT_FALLBACK_LANG = 'ru';

const INTENSIV_URL =
  'https://www.li-astrology.com.ua/intensiv/?utm_source=bot&utm_medium=gift&utm_campaign=lead_magnet';

// Telegram file_id cache per language (process-wide; one Fly machine).
const fileIdCache = new Map<string, string>();

export const GIFT_PAYLOAD_PREFIX = 'gift';

export function isGiftPayload(payload: string | undefined): boolean {
  return !!payload && (payload === GIFT_PAYLOAD_PREFIX || payload.startsWith(`${GIFT_PAYLOAD_PREFIX}__`));
}

/** `gift__ig_bio` → `ig_bio`; bare `gift` → `direct`. */
export function giftSource(payload: string): string {
  const raw = payload.slice(GIFT_PAYLOAD_PREFIX.length + 2);
  const clean = raw.replace(/[^A-Za-z0-9_-]/g, '').slice(0, 48);
  return clean || 'direct';
}

export async function handleGift(ctx: BotContext, payload: string): Promise<void> {
  const from = ctx.from!;
  const source = giftSource(payload);

  // First-touch attribution; no-op if the user already has a source.
  await setUserSource(from.id, `gift:${source}`);

  await cleanAndSend(ctx, ctx.t.gift.intro(from.first_name ?? ''));

  await sendGiftDocument(ctx);

  await cleanAndSend(ctx, ctx.t.gift.after, {
    reply_markup: new InlineKeyboard()
      .url(ctx.t.gift.intensivButton, INTENSIV_URL)
      .row()
      .text(ctx.t.waitlist.browseCatalog, 'catalog')
      .row()
      .text(ctx.t.common.home, 'home'),
  });
}

async function sendGiftDocument(ctx: BotContext): Promise<void> {
  const lang = pickLang(ctx);
  const cached = fileIdCache.get(lang);
  const chatId = ctx.chat!.id;
  const caption = ctx.t.gift.caption;

  try {
    const sent = cached
      ? await ctx.api.sendDocument(chatId, cached, { caption })
      : await ctx.api.sendDocument(
          chatId,
          new InputFile(GIFT_FILES[lang], ctx.t.gift.fileName),
          { caption },
        );
    if (!cached && sent.document?.file_id) fileIdCache.set(lang, sent.document.file_id);
  } catch (e) {
    console.error('gift: sendDocument failed', e);
    // Cache may hold a stale file_id (e.g. after bot token change) — drop it
    // so the next attempt re-uploads from disk.
    fileIdCache.delete(lang);
    await cleanAndSend(ctx, ctx.t.gift.sendFailed);
  }
}

function pickLang(ctx: BotContext): string {
  // Locale objects are singletons, so identity tells us the language.
  const lang = (ctx.t as unknown) === ru ? 'ru' : 'uk';
  return GIFT_FILES[lang] && existsSync(GIFT_FILES[lang]) ? lang : GIFT_FALLBACK_LANG;
}
